import * as T from 'three';
import {OrbitControls} from '../vendor/OrbitControls.js';
import {makePerson,animatePerson,part} from './people/models.mjs';
import {population,roleOf} from './people/core.mjs';
import {createTown,advanceHour,addHousehold,toggleBusiness,routine,JOBS,staffing} from './economy.mjs';
import {addIncident,clock} from './civics.mjs';
const $=id=>document.getElementById(id),key='town-life-v1';let s=createTown(),paused=matchMedia('(prefers-reduced-motion: reduce)').matches,elapsed=0,last=0,selected=0,actors=[],labels=[],sceneGroup;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.version===1&&saved.households?.length>=1&&saved.households.length<=24&&saved.businesses?.length===12&&Number.isInteger(saved.hour)&&saved.hour>=0&&saved.hour<24)s=saved;}catch{}
const people=population(43,'alder'),roleMap={woodland:'farmer',craft:'mechanic',merchant:'grocer'};
const scene=new T.Scene();scene.background=new T.Color('#dce4d5');scene.add(new T.HemisphereLight('#fff5dc','#809476',2.6));const sun=new T.DirectionalLight('#fff3dc',3);sun.position.set(-20,60,20);scene.add(sun);
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;$('world').append(renderer.domElement);
const camera=new T.PerspectiveCamera(40,1,.1,400),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.47;controls.minDistance=8;controls.maxDistance=170;
const sites={market:{x:0,z:0,door:[0,0],lane:0,label:'Market square'},park:{x:14,z:0,door:[14,0],lane:0,label:'Commons'},farmer:{x:-53,z:-14,door:[-48,-6],lane:-6,label:'Countryside · growers'},woodland:{x:-53,z:14,door:[-48,6],lane:6,label:'Countryside · timber'}};
for(const [i,[id,label]]of JOBS.filter(j=>!['farmer','woodland','merchant'].includes(j[0])).entries()){const row=i<5?-1:1,x=[-31,-17,-7,9,23][i%5];sites[id]={x,z:row*13,door:[x,row*8.8],lane:row*6,label};}
sites.school=sites.teacher;sites.jail={x:27,z:13,door:[27,8.8],lane:6,label:'Civic custody & support'};sites.merchant=sites.market;
function homeSite(i){const row=i%2?-1:1,column=Math.floor(i/2)%6,band=Math.floor(i/12);return {x:-36+column*14,z:row*(31+band*15),door:[-36+column*14,row*(27+band*15)],lane:row*(23+band*15),label:s.households[i].name+' home'};}
function save(){try{localStorage.setItem(key,JSON.stringify(s));}catch{$('activity').textContent='Browser saving unavailable. This town will last for this session.';}}
const box=(g,c,sz,p)=>part(g,'box',c,sz,p);
function building(site,color,home=false){const {x,z}=site,g=new T.Group();box(g,'#d5cfba',[9,.1,9],[x,0,z]);box(g,color,[7,3.2,6],[x,1.6,z]);box(g,home?'#8b7968':'#72816b',[7.6,.3,6.5],[x,3.4,z]);const front=z<0?1:-1;box(g,'#53665b',[1.2,2,.12],[x,1,z+front*3.05]);for(const dx of [-2.3,2.3])box(g,'#b9d0c3',[1.2,1.2,.14],[x+dx,1.9,z+front*3.06]);sceneGroup.add(g);const el=document.createElement('span');el.textContent=site.label;$('labels').append(el);labels.push({el,position:new T.Vector3(x,4.4,z)});}
function build(){if(sceneGroup)scene.remove(sceneGroup);sceneGroup=new T.Group();scene.add(sceneGroup);labels=[];$('labels').replaceChildren();box(sceneGroup,'#a7b68d',[130,.3,105],[-6,-.3,0]);for(const z of [-38,-23,-6,0,6,23,38])box(sceneGroup,'#d1c5a7',[115,.06,z===0?7:3.2],[-5,0,z]);box(sceneGroup,'#d1c5a7',[3.2,.07,90],[0,0,0]);box(sceneGroup,'#d8cdb3',[14,.08,12],[0,.03,0]);for(const site of Object.values(sites))if(!['Market square','Commons'].includes(site.label)&&!site.label.startsWith('Countryside')&&site!==sites.school)building(site,'#d5d5ba');building(sites.school,'#c7cfad');
 for(const h of s.households){sites['home'+h.id]=homeSite(h.id);building(sites['home'+h.id],h.id%2?'#d7c6a8':'#c7c9b1',true);const p=sites['home'+h.id];box(sceneGroup,'#d1c5a7',[1.7,.07,5],[p.x,.01,(p.door[1]+p.lane)/2]);}
 for(const x of [-5,5])for(const z of [-3,3]){box(sceneGroup,'#a58b63',[3,1,.9],[x,.5,z]);for(const dx of [-1.3,1.3])box(sceneGroup,'#786c50',[.1,2.5,.1],[x+dx,1.25,z]);box(sceneGroup,z<0?'#b88667':'#718e7b',[3.4,.13,1.7],[x,2.5,z]);for(let i=0;i<5;i++)part(sceneGroup,'sphere',i%2?'#b7a15b':'#a9674d',[.16,.14,.16],[x-1+i*.5,1.1,z]);}
 for(let i=0;i<6;i++){box(sceneGroup,'#8b965a',[12,.15,1.1],[-53,.05,-19+i*2]);}for(const x of [-58,-53,-48])for(const z of [10,17]){part(sceneGroup,'cylinder','#887354',[.2,2.3,.2],[x,1,z]);part(sceneGroup,'sphere','#6d875b',[2,2.4,2],[x,3,z]);}
 for(const x of [12,17]){part(sceneGroup,'cylinder','#877154',[.16,2,.16],[x,1,2]);part(sceneGroup,'sphere','#6d875b',[1.5,1.9,1.5],[x,3,2]);box(sceneGroup,'#9e8967',[3,.2,1],[x,.5,-2]);}
 actors=[];for(const h of s.households)for(let member=0;member<h.adults+h.children;member++){const id=member>=h.adults?'student':h.jobs[member],source=people.find(p=>p.role===(roleMap[id]||id))||people[0],person=structuredClone(source);person.index=h.id*4+member;person.appearance.skin=['#e2ba98','#8e6148','#654434','#bc8969'][(h.id+member)%4];person.id=`${h.id}:${member}`;const model=makePerson(person),position=new T.Vector2(...sites['home'+h.id].door);model.position.set(position.x,0,position.y);sceneGroup.add(model);actors.push({h:h.id,member,person,model,position,path:[],target:null});}
 $('household').replaceChildren(...s.households.map(h=>{const o=document.createElement('option');o.value=h.id;o.textContent=h.name+' household';return o;}));$('household').value=selected;update();}
function itinerary(a,target){const to=sites[target]||sites.market,from=sites[a.target]||sites['home'+a.h],f=from.lane,t=to.lane;return [[a.position.x,f],[0,f],[0,t],[to.door[0],t],to.door].map(p=>new T.Vector2(...p));}
function fit(){camera.position.set(78,88,100);controls.target.set(-5,0,0);controls.update();}
function update(){const children=s.households.reduce((n,h)=>n+h.children,0),adult=s.households.length*2;$('clock').textContent=`Day ${s.day} · ${String(s.hour).padStart(2,'0')}:00`;$('pause').textContent=paused?'Resume':'Pause';$('add').disabled=s.households.length>=24;
 $('stats').innerHTML=[['Households',s.households.length],['Residents',adult+children],['Market trades',s.transactions],['Meals served',s.meals],['Open civic cases',(s.cases||[]).filter(c=>c.status==='open').length]].map(([k,v])=>`<div class="stat"><strong>${v}</strong><small>${k}</small></div>`).join('');
 const h=s.households[selected]||s.households[0];$('family').innerHTML=`<p><b>${h.adults} adults · ${h.children} children</b><br>${h.cash} credits · ${h.food} food in pantry</p>`+Array.from({length:h.adults+h.children},(_,i)=>`<div class="member"><b>${i<h.adults?JOBS.find(j=>j[0]===h.jobs[i])[1]:'Child · pupil'}</b>${routine(s,h,i).text}</div>`).join('');
 $('services').innerHTML=Object.entries(s.services).map(([k,v])=>`<div class="service"><span>${k[0].toUpperCase()+k.slice(1)}</span><span>${v.local}/${v.demand} local${v.outside?' + visiting help':''}</span></div>`).join('')||'<p>Services begin at 06:00.</p>';
 $('workplaces').replaceChildren(...s.businesses.map(b=>{const btn=document.createElement('button');btn.textContent=`${b.label} · ${staffing(s,b.id)} working · ${b.open?'Open':'Closed'}`;btn.setAttribute('aria-pressed',String(b.open));btn.onclick=()=>{s=toggleBusiness(s,b.id);save();update();};return btn;}));
 const cases=$('cases');cases.replaceChildren();if(!s.cases?.length)cases.innerHTML='<p class="note">No active incident. The town is going about its day.</p>';for(const c of [...(s.cases||[])].reverse().slice(0,6)){const el=document.createElement('section');el.className='case';const title=document.createElement('h3');title.textContent=`Case ${c.id} · ${{injury:'Walkway injury',theft:'Market goods',report:'Missing-goods report',serious:'Property damage'}[c.type]}`;el.append(title);const badge=document.createElement('span');badge.className='badge';badge.textContent=c.stage.replaceAll('-',' ');el.append(badge);const p=document.createElement('p');p.textContent=c.history.at(-1);el.append(p);if(c.type==='theft'&&['reported','investigating','hearing'].includes(c.stage)){const l=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=c.consent;input.onchange=()=>{c.consent=input.checked;save();};l.append(input,' Both parties consent to a restorative meeting');el.append(l);}const d=document.createElement('details'),sum=document.createElement('summary');sum.textContent='Case history';d.append(sum);const list=document.createElement('ol');for(const text of c.history){const li=document.createElement('li');li.textContent=text;list.append(li);}d.append(list);el.append(d);cases.append(el);}
 $('ledger').replaceChildren(...s.ledger.slice(0,30).map(r=>{const tr=document.createElement('tr');for(const text of [`D${r.day} ${r.hour}:00`,`${r.from} → ${r.to}`,`${r.quantity} ${r.good} · ${r.kind}`,r.value]){const td=document.createElement('td');td.textContent=text;tr.append(td);}return tr;}));
 $('journal').replaceChildren(...[...s.events,...(s.civicLog||[])].sort((a,b)=>b.day-a.day||b.hour-a.hour).slice(0,12).map(e=>{const p=document.createElement('p'),small=document.createElement('small');small.textContent=`Day ${e.day} · ${e.hour}:00`;p.append(small,e.text);return p;}));$('activity').textContent=`${adult+children} residents · ${children} schoolchildren · drag to orbit, scroll to zoom`;
}
function step(){s=advanceHour(s);save();update();}
$('pause').onclick=()=>{paused=!paused;update();};$('hour').onclick=()=>{elapsed=0;step();};$('fit').onclick=fit;$('close').onclick=()=>{camera.position.set(24,27,35);controls.target.set(0,0,0);};$('household').onchange=()=>{selected=Number($('household').value);update();const p=sites['home'+selected];controls.target.set(p.x,0,p.z);camera.position.set(p.x+15,18,p.z+22);};$('add').onclick=()=>{s=addHousehold(s);save();build();};$('reset').onclick=()=>{if(confirm('Replace this browser’s town with a new town?')){s=createTown();selected=0;elapsed=0;save();build();fit();}};
for(const b of document.querySelectorAll('[data-incident]'))b.onclick=()=>{s=addIncident(s,b.dataset.incident);save();update();};$('names').onchange=()=>{$('labels').hidden=!$('names').checked;};
new ResizeObserver(()=>{const r=$('world').getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe($('world'));
function frame(ms){const dt=Math.min(.1,(ms-last)/1000||0);last=ms;const speed=Number($('speed').value);if(!paused){elapsed+=dt*speed;while(elapsed>=8){elapsed-=8;step();}for(const a of actors){const activity=routine(s,s.households[a.h],a.member);if(activity.place!==a.target){a.path=itinerary(a,activity.place);a.target=activity.place;}let budget=dt*speed*4.5,moved=0;while(budget>0&&a.path.length){const v=a.path[0].clone().sub(a.position),len=v.length(),amount=Math.min(len,budget);if(len<.01){a.path.shift();continue;}a.position.addScaledVector(v,amount/len);a.model.rotation.y=Math.atan2(v.x,v.y);budget-=amount;moved+=amount;if(amount===len)a.path.shift();}a.model.position.set(a.position.x+Math.sin(a.person.index*2.1)*.4,0,a.position.y+Math.cos(a.person.index*2.1)*.4);animatePerson(a.model,activity,moved,dt*speed,false);}}controls.update();for(const l of labels){const p=l.position.clone().project(camera);l.el.style.left=((p.x+1)/2*$('world').clientWidth)+'px';l.el.style.top=((-p.y+1)/2*$('world').clientHeight)+'px';l.el.hidden=p.z>1;}renderer.render(scene,camera);requestAnimationFrame(frame);}
build();fit();requestAnimationFrame(frame);
